def ref(inp):
    lines = inp.strip("\n").split("\n")
    n, m = map(int, lines[0].split())
    s = lines[1].strip()

    # Brute force: for each k = number of logo shirts bought (0, 1, 2, ...),
    # check by exhaustive search whether a valid assignment of shirts exists.
    # Shirts 0..m-1 are plain, m..m+k-1 are logo.
    # State: day index and the set of shirts worn since the last wash.
    # On '0' days nothing is worn and all shirts are washed.
    # On '1' days any shirt not yet worn since the last wash may be used.
    # On '2' days only an unworn logo shirt may be used.
    def feasible(k):
        total = m + k
        memo = {}

        def go(i, used):
            key = (i, used)
            if key in memo:
                return memo[key]
            if i == n:
                res = True
            elif s[i] == "0":
                res = go(i + 1, frozenset())
            else:
                if s[i] == "1":
                    allowed = range(total)
                else:
                    allowed = range(m, total)
                res = False
                for sh in allowed:
                    if sh not in used and go(i + 1, used | {sh}):
                        res = True
                        break
            memo[key] = res
            return res

        return go(0, frozenset())

    k = 0
    while not feasible(k):
        k += 1
    return str(k)
